from pathlib import Path

ROOT=Path('profesional')
INDEX=ROOT/'index.html'
AUTH=ROOT/'assets/js/security/auth-permissions.js'
MOD=ROOT/'assets/js/modules/service-sheets.js'
PUBLIC=ROOT/'hojas-servicio-aceptar.html'
if not INDEX.exists() or not AUTH.exists():
    raise SystemExit('Faltan archivos profesionales base')
MOD.parent.mkdir(parents=True,exist_ok=True)

js=r'''/* Tráfico App Profesional · Control de Hojas de Servicio · v1 */
(function(){
 if(window.__ccServiceSheetsV1)return;window.__ccServiceSheetsV1=true;
 const sb=()=>window.gmSupabase, esc=v=>String(v==null?'':v).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
 const six=v=>String(Math.max(0,Number(v)||0)).padStart(6,'0');
 const fmt=v=>v?new Date(v).toLocaleString('es-MX'):'—';
 let D={series:[],anios:[],operadores:[],resumen:{},asignacionesResponsable:[],ultimosFolios:[],asignacionesOperador:[]};
 const perm=p=>window.CC_ACCESS?.rol==='ADMIN'||(typeof window.ccPerm==='function'&&window.ccPerm('hojas_servicio.'+p));
 async function load(){const r=await sb().rpc('hs_list');if(r.error)throw r.error;if(!r.data?.ok)throw new Error(r.data?.error||'No se pudo cargar Hojas de Servicio');D=r.data;render();}
 function modal(title,html,save){const ov=document.createElement('div');ov.style='position:fixed;inset:0;background:rgba(15,23,42,.76);z-index:100120;display:flex;align-items:center;justify-content:center;padding:16px';ov.innerHTML='<div style="background:#fff;width:min(820px,97vw);max-height:94vh;overflow:auto;border-radius:16px"><div style="background:#0f172a;color:#fff;padding:15px 18px;display:flex;justify-content:space-between"><strong>'+esc(title)+'</strong><button data-x style="border:0;background:none;color:#fff;font-size:22px">×</button></div><form style="padding:18px">'+html+'<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:15px"><button type="button" class="cc-btn cc-btn-light" data-cancel>Cancelar</button><button type="submit" class="cc-btn cc-btn-primary">Guardar</button></div></form></div>';document.body.appendChild(ov);const close=()=>ov.remove();ov.querySelector('[data-x]').onclick=close;ov.querySelector('[data-cancel]').onclick=close;ov.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;try{await save(new FormData(e.currentTarget),e.currentTarget);close();await load()}catch(x){alert(x.message||x);b.disabled=false}};return ov}
 const active=x=>(x||[]).filter(a=>String(a.estatus||'ACTIVO').toUpperCase()==='ACTIVO');
 const opts=(xs,f)=>xs.map(x=>'<option value="'+esc(x.id)+'">'+esc(f(x))+'</option>').join('');
 function openView(v,b){document.querySelectorAll('#ccPanelHojasServicio .hs-view').forEach(x=>x.style.display='none');document.getElementById('hsView'+v).style.display='block';document.querySelectorAll('#ccPanelHojasServicio [data-hsv]').forEach(x=>x.className='cc-btn cc-btn-light');if(b)b.className='cc-btn cc-btn-primary'}
 function generate(){if(!perm('generar'))return alert('Sin permiso para generar folios.');const ss=active(D.series),ys=active(D.anios);if(!ss.length||!ys.length)return alert('Primero agrega Serie y Año en Catálogos.');const ov=modal('Generar folios','<div class="cc-config-alert" style="margin-bottom:12px"><strong>Formato:</strong> SERIE-AÑO-000000. Puedes crear uno solo usando el mismo inicio y fin.</div><div class="cc-grid"><div class="cc-field"><label>Serie *</label><select name="serieId" required>'+opts(ss,x=>x.codigo)+'</select></div><div class="cc-field"><label>Año *</label><select name="anioId" required>'+opts(ys,x=>x.anio)+'</select></div><div class="cc-field"><label>Desde *</label><input name="desde" type="number" min="0" max="999999" value="0" required></div><div class="cc-field"><label>Hasta *</label><input name="hasta" type="number" min="0" max="999999" value="0" required></div></div><div id="hsPreview" class="cc-note" style="margin-top:10px"></div>',async fd=>{const r=await sb().rpc('hs_generate_folios',{p_item:{serieId:fd.get('serieId'),anioId:fd.get('anioId'),desde:Number(fd.get('desde')),hasta:Number(fd.get('hasta'))}});if(r.error)throw r.error;alert('Folios generados: '+Number(r.data?.generados||0))});const form=ov.querySelector('form'),pre=ov.querySelector('#hsPreview');const pv=()=>{const s=ss.find(x=>x.id===form.serieId.value),y=ys.find(x=>x.id===form.anioId.value);pre.textContent=s&&y?'Vista previa: '+s.codigo+'-'+y.anio+'-'+six(form.desde.value)+'  →  '+s.codigo+'-'+y.anio+'-'+six(form.hasta.value):''};form.oninput=pv;pv()}
 function assignResponsible(){if(!perm('asignar_responsable'))return alert('Sin permiso.');const ss=active(D.series),ys=active(D.anios);modal('Asignar rango a responsable','<div class="cc-config-alert" style="margin-bottom:12px">Solo se pueden asignar rangos completos que todavía estén en estado <b>NUEVO</b>. Al crear la asignación se genera un enlace de aceptación y firma.</div><div class="cc-grid"><div class="cc-field"><label>Serie *</label><select name="serieId">'+opts(ss,x=>x.codigo)+'</select></div><div class="cc-field"><label>Año *</label><select name="anioId">'+opts(ys,x=>x.anio)+'</select></div><div class="cc-field"><label>Desde *</label><input name="desde" type="number" min="0" max="999999" required></div><div class="cc-field"><label>Hasta *</label><input name="hasta" type="number" min="0" max="999999" required></div><div class="cc-field"><label>Responsable *</label><input name="responsableNombre" required></div><div class="cc-field"><label>Correo</label><input name="responsableEmail" type="email"></div></div>',async fd=>{const r=await sb().rpc('hs_create_responsible_assignment',{p_item:{serieId:fd.get('serieId'),anioId:fd.get('anioId'),desde:Number(fd.get('desde')),hasta:Number(fd.get('hasta')),responsableNombre:fd.get('responsableNombre'),responsableEmail:fd.get('responsableEmail'),hours:168}});if(r.error)throw r.error;const url=location.origin+location.pathname.replace(/[^/]+$/,'')+'hojas-servicio-aceptar.html?t='+encodeURIComponent(r.data.token);try{await navigator.clipboard.writeText(url)}catch(_){ }prompt('Asignación creada. Copia este enlace para que el responsable acepte y firme:',url)})}
 function assignOperator(){if(!perm('asignar_operador'))return alert('Sin permiso.');const aa=(D.asignacionesResponsable||[]).filter(x=>x.estatus==='ACEPTADA'),ops=active(D.operadores);if(!aa.length)return alert('No hay rangos aceptados por responsables.');if(!ops.length)return alert('No hay operadores activos.');modal('Repartir folios a operador','<div class="cc-grid"><div class="cc-field"><label>Custodia del responsable *</label><select name="asignacionId">'+opts(aa,x=>x.responsableNombre+' · '+x.serie+'-'+x.anio+' · '+six(x.desde)+' a '+six(x.hasta))+'</select></div><div class="cc-field"><label>Operador *</label><select name="operadorId">'+opts(ops,x=>x.nombre+(x.numeroEmpleado?' · '+x.numeroEmpleado:''))+'</select></div><div class="cc-field"><label>Desde *</label><input name="desde" type="number" min="0" max="999999" required></div><div class="cc-field"><label>Hasta *</label><input name="hasta" type="number" min="0" max="999999" required></div></div><div class="cc-field"><label>Observaciones</label><textarea name="observaciones"></textarea></div>',async fd=>{const r=await sb().rpc('hs_assign_operator_range',{p_item:{asignacionId:fd.get('asignacionId'),operadorId:fd.get('operadorId'),desde:Number(fd.get('desde')),hasta:Number(fd.get('hasta')),observaciones:fd.get('observaciones')}});if(r.error)throw r.error;alert('Folios asignados al operador: '+Number(r.data?.asignados||0))})}
 function cat(tipo,x={}){if(!perm('catalogos'))return alert('Sin permiso.');const isS=tipo==='SERIE';modal((x.id?'Editar ':'Agregar ')+(isS?'Serie':'Año'),isS?'<div class="cc-field"><label>Serie *</label><input name="codigo" required value="'+esc(x.codigo||'')+'" placeholder="Ej. A"></div><div class="cc-field"><label>Descripción</label><input name="descripcion" value="'+esc(x.descripcion||'')+'"></div>':'<div class="cc-field"><label>Año *</label><input name="anio" type="number" min="2000" max="2100" required value="'+esc(x.anio||new Date().getFullYear())+'"></div>',async fd=>{const item=isS?{id:x.id||'',codigo:fd.get('codigo'),descripcion:fd.get('descripcion'),estatus:'ACTIVO'}:{id:x.id||'',anio:Number(fd.get('anio')),estatus:'ACTIVO'};const r=await sb().rpc('hs_save_catalog',{p_tipo:tipo,p_item:item});if(r.error)throw r.error})}
 function render(){const r=D.resumen||{},k=document.getElementById('hsKpis');if(k)k.innerHTML=[['Total',r.total],['Nuevos',r.nuevos],['Pend. aceptación',r.pendienteAceptacion],['En custodia',r.enCustodia],['Con operador',r.asignadosOperador]].map(x=>'<div class="cc-ant-kpi"><small>'+x[0]+'</small><strong>'+Number(x[1]||0).toLocaleString('es-MX')+'</strong></div>').join('');const fb=document.getElementById('hsFoliosBody');if(fb)fb.innerHTML=(D.ultimosFolios||[]).map(x=>'<tr><td><strong>'+esc(x.folio)+'</strong></td><td>'+esc(x.estatus)+'</td><td>'+esc(x.responsable_nombre||'—')+'</td><td>'+esc(x.operador_nombre||'—')+'</td></tr>').join('')||'<tr><td colspan="4" style="text-align:center;padding:20px">Sin folios.</td></tr>';const rb=document.getElementById('hsRespBody');if(rb)rb.innerHTML=(D.asignacionesResponsable||[]).map(x=>'<tr><td>'+esc(x.serie)+'-'+esc(x.anio)+'</td><td>'+six(x.desde)+' → '+six(x.hasta)+'</td><td><strong>'+esc(x.responsableNombre)+'</strong><div style="font-size:9px;color:#64748b">'+esc(x.responsableEmail||'')+'</div></td><td>'+esc(x.estatus)+'</td><td>'+fmt(x.aceptadoAt)+'</td></tr>').join('')||'<tr><td colspan="5" style="text-align:center;padding:20px">Sin asignaciones.</td></tr>';const ob=document.getElementById('hsOpBody');if(ob)ob.innerHTML=(D.asignacionesOperador||[]).map(x=>'<tr><td><strong>'+esc(x.folio)+'</strong></td><td>'+esc(x.operador)+'</td><td>'+esc(x.responsable||'—')+'</td><td>'+fmt(x.fecha)+'</td></tr>').join('')||'<tr><td colspan="4" style="text-align:center;padding:20px">Sin entregas a operadores.</td></tr>';const sc=document.getElementById('hsSeries'),yc=document.getElementById('hsAnios');if(sc)sc.innerHTML=(D.series||[]).map(x=>'<div style="padding:8px;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between"><strong>'+esc(x.codigo)+'</strong><button class="cc-btn cc-btn-light" data-s="'+x.id+'">Editar</button></div>').join('')||'<div class="cc-note">Sin series.</div>';if(yc)yc.innerHTML=(D.anios||[]).map(x=>'<div style="padding:8px;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between"><strong>'+x.anio+'</strong><button class="cc-btn cc-btn-light" data-y="'+x.id+'">Editar</button></div>').join('')||'<div class="cc-note">Sin años.</div>';sc?.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>cat('SERIE',D.series.find(x=>x.id===b.dataset.s)||{}));yc?.querySelectorAll('[data-y]').forEach(b=>b.onclick=()=>cat('ANIO',D.anios.find(x=>x.id===b.dataset.y)||{}))}
 function install(){const root=document.getElementById('controlCajasSection'),tabs=root?.querySelector('.cc-tabs');if(!root||!tabs)return;let btn=document.getElementById('ccTabHojasServicio');if(!btn){btn=document.createElement('button');btn.id='ccTabHojasServicio';btn.className='cc-tab';btn.innerHTML='<i class="fa-solid fa-file-lines mr-1"></i>Control de Hojas de Servicio';const ab=[...tabs.querySelectorAll('.cc-tab')].find(x=>(x.textContent||'').includes('Control de Anticipos'));ab?ab.after(btn):tabs.appendChild(btn)}let p=document.getElementById('ccPanelHojasServicio');if(!p){p=document.createElement('div');p.id='ccPanelHojasServicio';p.className='cc-panel';p.innerHTML='<div class="cc-toolbar"><div><strong>Control de Hojas de Servicio</strong><div class="cc-note">Generación, custodia y entrega de folios a operadores.</div></div><button class="cc-btn cc-btn-light" data-refresh>Actualizar</button></div><div id="hsKpis" class="cc-ant-kpis"></div><div style="display:flex;gap:7px;flex-wrap:wrap;margin:10px 0"><button class="cc-btn cc-btn-primary" data-hsv="Folios">Folios</button><button class="cc-btn cc-btn-light" data-hsv="Responsables">Asignar a responsable</button><button class="cc-btn cc-btn-light" data-hsv="Operadores">Repartir a operadores</button><button class="cc-btn cc-btn-light" data-hsv="Catalogos">Catálogos</button></div><div id="hsViewFolios" class="hs-view"><div class="cc-toolbar"><strong>Folios</strong><button class="cc-btn cc-btn-primary" data-gen>Generar folios</button></div><div class="cc-inv-wrap"><table class="cc-ant-table"><thead><tr><th>FOLIO</th><th>ESTATUS</th><th>RESPONSABLE</th><th>OPERADOR</th></tr></thead><tbody id="hsFoliosBody"></tbody></table></div></div><div id="hsViewResponsables" class="hs-view" style="display:none"><div class="cc-toolbar"><strong>Custodia por responsable</strong><button class="cc-btn cc-btn-primary" data-resp>Asignar rango</button></div><div class="cc-inv-wrap"><table class="cc-ant-table"><thead><tr><th>SERIE/AÑO</th><th>RANGO</th><th>RESPONSABLE</th><th>ESTATUS</th><th>ACEPTADO</th></tr></thead><tbody id="hsRespBody"></tbody></table></div></div><div id="hsViewOperadores" class="hs-view" style="display:none"><div class="cc-toolbar"><strong>Folios entregados a operadores</strong><button class="cc-btn cc-btn-primary" data-op>Asignar rango</button></div><div class="cc-inv-wrap"><table class="cc-ant-table"><thead><tr><th>FOLIO</th><th>OPERADOR</th><th>RESPONSABLE</th><th>FECHA</th></tr></thead><tbody id="hsOpBody"></tbody></table></div></div><div id="hsViewCatalogos" class="hs-view" style="display:none"><div class="cc-ant-report-grid"><div class="cc-config-card"><div class="cc-toolbar"><strong>Series</strong><button class="cc-btn cc-btn-primary" data-add-serie>Agregar</button></div><div id="hsSeries"></div></div><div class="cc-config-card"><div class="cc-toolbar"><strong>Años</strong><button class="cc-btn cc-btn-primary" data-add-anio>Agregar</button></div><div id="hsAnios"></div></div></div></div>';root.appendChild(p)}const allowed=()=>perm('ver');btn.style.display=allowed()?'':'none';btn.onclick=()=>{if(!allowed())return alert('Sin permiso para Hojas de Servicio.');root.querySelectorAll('.cc-tab').forEach(x=>x.classList.remove('active'));root.querySelectorAll('.cc-panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');p.classList.add('active');load().catch(e=>alert(e.message||e))};p.querySelectorAll('[data-hsv]').forEach(b=>b.onclick=()=>openView(b.dataset.hsv,b));p.querySelector('[data-gen]').onclick=generate;p.querySelector('[data-resp]').onclick=assignResponsible;p.querySelector('[data-op]').onclick=assignOperator;p.querySelector('[data-add-serie]').onclick=()=>cat('SERIE');p.querySelector('[data-add-anio]').onclick=()=>cat('ANIO');p.querySelector('[data-refresh]').onclick=()=>load().catch(e=>alert(e.message||e));}
 window.ccHsOpen=()=>document.getElementById('ccTabHojasServicio')?.click();
 function boot(){if(window.CC_AUTH_READY&&window.gmSupabase){install()}else setTimeout(boot,500)}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,600));else setTimeout(boot,600);
})();
'''
MOD.write_text(js,encoding='utf-8')

html=INDEX.read_text(encoding='utf-8')
tag='<script src="assets/js/modules/service-sheets.js"></script>'
if tag not in html:
    html=html.replace('</body>',tag+'\n</body>',1)
INDEX.write_text(html,encoding='utf-8')

auth=AUTH.read_text(encoding='utf-8')
if "['hojas_servicio','Control de Hojas de Servicio'" not in auth:
    needle=" ['notificaciones','Notificaciones'"
    entry=" ['hojas_servicio','Control de Hojas de Servicio',[['ver','Ver módulo'],['generar','Generar folios'],['asignar_responsable','Asignar a responsable'],['asignar_operador','Asignar a operadores'],['catalogos','Catálogos']]],\n"
    if needle not in auth: raise SystemExit('No se encontró lugar para permiso Hojas de Servicio')
    auth=auth.replace(needle,entry+needle,1)
AUTH.write_text(auth,encoding='utf-8')

PUBLIC.write_text(r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aceptar hojas de servicio</title><style>body{margin:0;font-family:Arial,sans-serif;background:#f1f5f9;color:#0f172a}.wrap{max-width:680px;margin:30px auto;padding:16px}.card{background:#fff;border-radius:18px;box-shadow:0 18px 45px #0f172a20;overflow:hidden}.head{background:#0f172a;color:#fff;padding:22px}.body{padding:22px}.box{background:#eff6ff;border:1px solid #bfdbfe;padding:14px;border-radius:12px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{font-size:12px;font-weight:bold;display:block;margin:10px 0 5px}input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #cbd5e1;border-radius:9px}canvas{width:100%;height:180px;border:1px dashed #94a3b8;border-radius:10px;touch-action:none;background:#fff}.btn{border:0;border-radius:9px;padding:11px 14px;font-weight:bold;cursor:pointer}.primary{background:#2563eb;color:#fff}.light{background:#e2e8f0}.actions{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><div class="head"><h2 style="margin:0">Aceptación de Hojas de Servicio</h2><div style="font-size:12px;color:#bfdbfe;margin-top:5px">Confirma la recepción del rango asignado.</div></div><div class="body" id="app">Cargando asignación...</div></div></div><script src="assets/js/vendor/supabase-sdk.js"></script><script src="assets/js/config/supabase-config.js"></script><script>(async()=>{const app=document.getElementById('app'),t=new URLSearchParams(location.search).get('t')||'';if(!window.supabase||!t){app.innerHTML='<b>Enlace inválido.</b>';return}const sb=window.supabase.createClient(window.GM_SUPABASE_URL,window.GM_SUPABASE_ANON_KEY,{auth:{persistSession:false,autoRefreshToken:false}});const r=await sb.rpc('hs_public_assignment',{p_token:t});if(r.error||!r.data?.ok){app.innerHTML='<b>No fue posible abrir esta asignación.</b><div style="margin-top:8px">'+(r.error?.message||r.data?.error||'Enlace inválido o vencido')+'</div>';return}const a=r.data.asignacion;app.innerHTML='<div class="box"><strong>'+a.folioDesde+' → '+a.folioHasta+'</strong><div style="margin-top:6px">Cantidad: '+a.cantidad+' hojas</div><div>Responsable: '+(a.responsableNombre||'')+'</div></div><label>Nombre de quien recibe *</label><input id="name" value="'+(a.responsableNombre||'').replace(/"/g,'&quot;')+'"><label>Firma electrónica *</label><canvas id="sig" width="900" height="250"></canvas><div class="actions"><button class="btn light" id="clear">Limpiar firma</button><button class="btn primary" id="accept">Aceptar y firmar</button></div><div id="msg" style="margin-top:12px"></div>';const c=document.getElementById('sig'),ctx=c.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';let down=false,has=false;const pos=e=>{const q=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:(p.clientX-q.left)*c.width/q.width,y:(p.clientY-q.top)*c.height/q.height}};const start=e=>{e.preventDefault();down=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)};const move=e=>{if(!down)return;e.preventDefault();const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();has=true};const end=e=>{e.preventDefault();down=false};['pointerdown','touchstart'].forEach(x=>c.addEventListener(x,start,{passive:false}));['pointermove','touchmove'].forEach(x=>c.addEventListener(x,move,{passive:false}));['pointerup','pointerleave','touchend'].forEach(x=>c.addEventListener(x,end,{passive:false}));document.getElementById('clear').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);has=false};document.getElementById('accept').onclick=async()=>{const n=document.getElementById('name').value.trim(),m=document.getElementById('msg'),b=document.getElementById('accept');if(!n)return m.textContent='Captura tu nombre.';if(!has)return m.textContent='Firma dentro del recuadro.';b.disabled=true;m.textContent='Guardando aceptación...';const z=await sb.rpc('hs_accept_assignment',{p_token:t,p_nombre:n,p_firma_data:c.toDataURL('image/png'),p_user_agent:navigator.userAgent});if(z.error||!z.data?.ok){m.textContent=z.error?.message||z.data?.error||'No se pudo guardar';b.disabled=false;return}m.innerHTML='<b style="color:#166534">Aceptación registrada correctamente.</b><br>Los folios quedaron bajo tu custodia.';document.getElementById('clear').disabled=true}})();</script></body></html>''',encoding='utf-8')

print('Control de Hojas de Servicio v1 agregado a versión profesional')
